const dicts: Record<Lang, Record<Key, string>> = { es, en };
const STORE_KEY = 'tiecoms:lang';

export function browserLang(): Lang {
  const prefs = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const l of prefs) {
    const base = (l || '').toLowerCase().slice(0, 2);
    if (base === 'es') return 'es';
    if (base === 'en') return 'en';
  }
  return 'en';
}

function stored(): Lang | null {
  try { const v = localStorage.getItem(STORE_KEY); return v === 'es' || v === 'en' ? v : null; } catch { return null; }
}

let current: Lang = stored() ?? browserLang();
const listeners = new Set<() => void>();
document.documentElement.lang = current;

/** null = seguir al navegador. */
export function setLang(l: Lang | null) {
  try { if (l) localStorage.setItem(STORE_KEY, l); else localStorage.removeItem(STORE_KEY); } catch {}
  current = l ?? browserLang();
  document.documentElement.lang = current;
  listeners.forEach((f) => f());
}
export const langPreference = (): Lang | null => stored();
export const getLang = () => current;
export const locale = () => (current === 'en' ? 'en-US' : 'es-CO');

export function useLang(): Lang {
  return useSyncExternalStore((f) => { listeners.add(f); return () => listeners.delete(f); }, () => current);
}

export function t(key: Key, vars: Record<string, string | number> = {}): string {
  const s = dicts[current][key] ?? es[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
}

export function tn(n: number, one: Key, many: Key) {
  return `${n} ${t(n === 1 ? one : many)}`;
}

/** Mensaje de error legible a partir del código del API (el texto del servidor está en español). */
export function errorText(e: any): string {
  // Un 502/503/504 sin cuerpo JSON (API reiniciándose): nunca «Bad Gateway» crudo.
  if (/^http_50[234]$/.test(e?.code ?? '')) return t('err.updating');
  if (e?.code === 'bad_request' && Array.isArray(e?.details) && e.details.length) {
    const paths = e.details.map((d: any) => d.path).filter(Boolean);
    return `${t('err.bad_request')}${paths.length ? `: ${[...new Set(paths)].join(', ')}` : ''}`;
  }
  const k = `err.${e?.code}` as Key;
  if (e?.code && k in es) return current === 'es' && e?.message ? e.message : t(k);
  if (e instanceof TypeError) return t('err.network');
  return e?.message || t('common.error');
}

/** Los mensajes de sistema llegan como {"k": clave, ...datos}; los antiguos, como texto plano. */
/**
 * La vista previa de la lista llega cortada a 140 caracteres: si el JSON no cierra, se toman las claves completas
 * ("k":"…", "subject":"…", números). Así no se ve JSON crudo en la barra.
 */
function lenientJson(body: string): any {
  try { return JSON.parse(body); } catch {}
  const out: Record<string, unknown> = {};
  for (const m of body.matchAll(/"(\w+)":("(?:[^"\\]|\\.)*"|-?\d+(?:\.\d+)?|true|false|null)/g)) {
    try { out[m[1]!] = JSON.parse(m[2]!); } catch {}
  }
  if (typeof out.k !== 'string') throw new Error('not a system message');
  return out;
}
export function systemText(body: string): string {
  if (!body.startsWith('{')) return body;
  try {
    const p = lenientJson(body);
    const key = (p.k === 'members.added' && p.history === 'all' ? 'sys.members.added.all' : p.k === 'side.started' && p.parentName ? 'sys.side.startedIn' : `sys.${p.k}`) as Key;
    if (typeof p.durationSec === 'number') p.duration = `${Math.floor(p.durationSec / 60)}:${String(p.durationSec % 60).padStart(2, '0')}`;
    if (p.startsAt) p.when = new Date(p.startsAt).toLocaleString(locale(), { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
    if (p.startsAt) p.time = new Date(p.startsAt).toLocaleTimeString(locale(), { hour: 'numeric', minute: '2-digit' });
    if (typeof p.dueDate === 'string') p.date = dueDateLabel(p.dueDate);
    return key in es ? t(key, p) : body;
  } catch { return body; }
}

/** «📷 3 fotos», «🎬 Video», «📎 contrato.pdf» a partir del resumen del API. */
export function voiceDuration(ms: number | null | undefined) {
  const total = Math.round((ms ?? 0) / 1000);
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}
export function attachmentSummaryText(a: { count: number; images: number; videos: number; files: number; firstName: string | null; voices?: number; voiceDurationMs?: number | null }): string {
  if (a.voices && a.voices === a.count) return a.voiceDurationMs ? t('voice.preview', { d: voiceDuration(a.voiceDurationMs) }) : t('voice.previewShort');
  if (a.images === a.count) return a.count === 1 ? t('att.photo') : t('att.photos', { n: a.count });
  if (a.videos === a.count) return a.count === 1 ? t('att.video') : t('att.videos', { n: a.count });
  if (a.images + a.videos === a.count) return t('att.media', { n: a.count });
  return a.count === 1 ? t('att.file', { name: a.firstName ?? '' }) : t('att.files', { n: a.count });
}

/** «30 sep» a partir de AAAA-MM-DD (sin corrimiento de zona). */
export function dueDateLabel(iso: string): string {
  const [y, m, d] = iso.split('-').map(Number);
  if (!y || !m || !d) return iso;
  return new Date(y, m - 1, d).toLocaleDateString(locale(), { day: 'numeric', month: 'short' });
}
